#!/usr/bin/env python3
"""Helpers for reconciling records ACROSS files (vendors, invoices, POs, ...).

Cross-file checks fail when you compare raw strings: "Acme Ltd" vs "Acme Limited"
are the same vendor, "GB29 NWBK ..." vs "GB29NWBK..." are the same IBAN, and
100.00 vs 100.001 are the same amount. Comparing them literally produces false
positives (flagging a clean record) AND false negatives. Use these helpers so
matching is neither too strict nor too loose.

    from reconcile import canonical_name, is_same_vendor, match_name, norm_id, amounts_equal

    match_name("Acme Ltd", ["Acme Limited", "Beta Inc"])  # -> "Acme Limited"
    norm_id("GB29 NWBK 6016 1331 9268 19") == norm_id("gb29nwbk60161331926819")  # True
    amounts_equal(100.0, 100.004)  # True (within tol)
"""

import re
from difflib import SequenceMatcher

# Company legal-suffix variants that mean the same entity. Normalised to a canon.
_SUFFIX_CANON = {
    "ltd": "ltd", "limited": "ltd",
    "inc": "inc", "incorporated": "inc",
    "corp": "corp", "corporation": "corp",
    "co": "co", "company": "co",
    "llc": "llc",
    "llp": "llp",
    "plc": "plc",
    "gmbh": "gmbh",
    "sa": "sa", "sas": "sa",
    "pty": "pty",
    "and": "and", "&": "and",
}


def canonical_name(name):
    """Lowercase, strip punctuation, collapse spaces, normalise legal suffixes."""
    if name is None:
        return ""
    s = str(name).lower()
    s = s.replace("&", " and ")
    s = re.sub(r"[^a-z0-9]+", " ", s)  # drop punctuation
    s = re.sub(r"\s+", " ", s).strip()
    tokens = «redacted» t) for t in s.split()]
    return " ".join(tokens).strip()


def name_similarity(a, b):
    """Similarity in [0,1] on canonicalised names."""
    return SequenceMatcher(None, canonical_name(a), canonical_name(b)).ratio()


def is_same_vendor(a, b, threshold=0.85):
    """True if two vendor names refer to the same vendor.

    Exact match after canonicalisation (so "Ltd"/"Limited" match) OR fuzzy
    similarity >= threshold. Lower the threshold for noisier data, raise it if
    you see false matches.
    """
    ca, cb = canonical_name(a), canonical_name(b)
    if ca and ca == cb:
        return True
    return name_similarity(a, b) >= threshold


def match_name(name, candidates, threshold=0.85):
    """Return the best-matching candidate name, or None if none is close enough."""
    best, best_score = None, 0.0
    cn = canonical_name(name)
    for cand in candidates:
        if canonical_name(cand) == cn and cn:
            return cand
        score = name_similarity(name, cand)
        if score > best_score:
            best, best_score = cand, score
    return best if best_score >= threshold else None


def norm_id(s):
    """Canonicalise an identifier (IBAN, PO number): drop spaces, uppercase."""
    if s is None:
        return ""
    return re.sub(r"\s+", "", str(s)).upper()


def ids_equal(a, b):
    return norm_id(a) == norm_id(b)


def amounts_equal(a, b, tol=0.01):
    """Tolerant float comparison (default within 0.01)."""
    try:
        return abs(float(a) - float(b)) <= tol
    except (TypeError, ValueError):
        return str(a) == str(b)


if __name__ == "__main__":
    print(__doc__)
